public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    Arrays.sort(nums);
    while (true) {
        List<Integer> one = new ArrayList<>();
        for (int v : nums) one.add(v);
        result.add(one);
        int i = nums.length - 1;
        while (i > 0 && nums[i - 1] >= nums[i]) i--;
        if (i <= 0) break;
        int j = nums.length - 1;
        while (nums[i - 1] >= nums[j]) j--;
        // swap
        int tmp = nums[i-1]; nums[i-1] = nums[j]; nums[j] = tmp;
        int lo = i, hi = nums.length - 1;
        while (lo < hi) {
            int t = nums[lo]; nums[lo] = nums[hi]; nums[hi] = t;
            lo++; hi--;
        }
    }
    return result;
}

