public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Find the shortest string to limit the number of candidate substrings
    String shortest = strings.get(0);
    for (String s : strings) {
        if (s.length() < shortest.length()) {
            shortest = s;
        }
    }
    int shortestLen = shortest.length();
    // Iterate over possible lengths from largest to smallest
    for (int len = shortestLen; len >= 1; len--) {
        // Iterate over all substrings of the current length in the shortest string
        for (int start = 0; start <= shortestLen - len; start++) {
            String candidate = shortest.substring(start, start + len);
            String reverseCandidate = new StringBuilder(candidate).reverse().toString();
            boolean valid = true;
            // Check whether each string in the list contains the candidate or its reverse
            for (String s : strings) {
                if (!(s.contains(candidate) || s.contains(reverseCandidate))) {
                    valid = false;
                    break;
                }
            }
            if (valid) {
                return len; // largest valid length found
            }
        }
    }
    return 0; // no common substring (or its reverse) found
}

