private static void dfs(char[][] grid, boolean[][] visited, int r, int c, int rows, int cols) {
    if (r < 0 || r >= rows || c < 0 || c >= cols) {
        return;
    }
    if (visited[r][c] || grid[r][c] != '@') {
        return;
    }
    visited[r][c] = true;
    for (int dr = -1; dr <= 1; dr++) {
        for (int dc = -1; dc <= 1; dc++) {
            if (dr == 0 && dc == 0) {
                continue;
            }
            dfs(grid, visited, r + dr, c + dc, rows, cols);
        }
    }
}

