public static int maxRegions(int N) {
    // Formula derived for the maximum number of regions formed by N triangles:
    // R(N) = 3N^2 - 3N + 2
    return 3 * N * N - 3 * N + 2;
}

public static int maxRegions(int N) {
    int regions = 1;
    for (int i = 0; i < N; i++) {
        regions *= 3;
    }
    return regions - 1;
}

public static int maxRegions(int N) {
    if (N <= 0) {
        return 1;
    }
    return 3 * N * N - 3 * N + 2;
}

public static int maxRegions(int N) {
    if (N < 1) {
        return 1;  // No triangles, only the whole plane
    }
    long regions = 3L * N * (N - 1) + 2L;  // 3N^2 - 3N + 2
    return (int) regions;
}

