public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || start.length == 0 || end == null || end.length == 0 || n <= 0) {
        return "cannot be travelled";
    }
    int s = start[0];
    int t = end[0];
    if (s < 0 || s >= n || t < 0 || t >= n) {
        return "cannot be travelled";
    }
    // Build adjacency list
    @SuppressWarnings("unchecked")
    List<Integer>[] adj = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new ArrayList<>();
    }
    for (int[] p : paths) {
        if (p == null || p.length < 2) {
            continue; // ignore invalid edges
        }
        int a = p[0];
        int b = p[1];
        if (a < 0 || a >= n || b < 0 || b >= n) {
            continue; // skip out-of-range edges
        }
        adj[a].add(b);
        adj[b].add(a);
    }
    // BFS from start to end
    boolean[] visited = new boolean[n];
    Queue<Integer> queue = new ArrayDeque<>();
    queue.offer(s);
    visited[s] = true;
    while (!queue.isEmpty()) {
        int curr = queue.poll();
        if (curr == t) {
            return "can be travelled";
        }
        for (int next : adj[curr]) {
            if (!visited[next]) {
                visited[next] = true;
                queue.offer(next);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }
    // Utility to convert coordinates to a unique key
    java.util.function.Function<int[], String> coordKey = coords -> {
        if (coords == null || coords.length != n) {
            return null;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append(coords[i]);
            if (i < n - 1) sb.append(',');
        }
        return sb.toString();
    };

    String startKey = coordKey.apply(start);
    String endKey = coordKey.apply(end);
    if (startKey == null || endKey == null) {
        return "cannot be travelled";
    }
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    for (int[] path : paths) {
        if (path == null || path.length != 2 * n) {
            continue; // skip invalid entries
        }
        int[] coordA = new int[n];
        int[] coordB = new int[n];
        System.arraycopy(path, 0, coordA, 0, n);
        System.arraycopy(path, n, coordB, 0, n);
        String aKey = coordKey.apply(coordA);
        String bKey = coordKey.apply(coordB);
        if (aKey == null || bKey == null) {
            continue;
        }
        graph.computeIfAbsent(aKey, k -> new java.util.ArrayList<>()).add(bKey);
        graph.computeIfAbsent(bKey, k -> new java.util.ArrayList<>()).add(aKey);
    }

    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbours = graph.get(current);
        if (neighbours != null) {
            for (String nb : neighbours) {
                if (nb.equals(endKey)) {
                    return "can be travelled";
                }
                if (!visited.contains(nb)) {
                    visited.add(nb);
                    queue.add(nb);
                }
            }
        }
    }

    return "cannot be travelled";
}

