public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Helper to convert coordinate array to a unique string key
    java.util.function.Function<int[], String> coordToKey = coord -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };

    // If start equals end, travel is trivially possible
    if (java.util.Arrays.equals(start, end)) {
        return "can be travelled";
    }

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> adjacency = new java.util.HashMap<>();
    for (int[] path : paths) {
        // Expect each path to be [x1, y1, x2, y2]
        if (path.length < 4) continue; // skip malformed
        int[] coord1 = new int[] { path[0], path[1] };
        int[] coord2 = new int[] { path[2], path[3] };
        String key1 = coordToKey.apply(coord1);
        String key2 = coordToKey.apply(coord2);
        adjacency.computeIfAbsent(key1, k -> new java.util.ArrayList<>()).add(key2);
        adjacency.computeIfAbsent(key2, k -> new java.util.ArrayList<>()).add(key1);
    }

    String startKey = coordToKey.apply(start);
    String endKey = coordToKey.apply(end);

    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbors = adjacency.getOrDefault(current, java.util.Collections.emptyList());
        for (String neighbor : neighbors) {
            if (neighbor.equals(endKey)) {
                return "can be travelled";
            }
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Build adjacency list based on path coordinates (assumed format: [x1, y1, x2, y2])
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] p : paths) {
        if (p.length < 4) continue; // skip invalid entries
        String a = p[0] + "," + p[1];
        String b = p[2] + "," + p[3];
        adj.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
        adj.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
    }

    String startKey = start[0] + "," + start[1];
    String endKey = end[0] + "," + end[1];

    // If start and end are the same, we can trivially travel
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // Simple BFS to check connectivity
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    if (!adj.containsKey(startKey) || !adj.containsKey(endKey)) {
        return "cannot be travelled";
    }

    queue.offer(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        if (current.equals(endKey)) {
            return "can be travelled";
        }
        for (String neighbor : adj.getOrDefault(current, java.util.Collections.emptyList())) {
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.offer(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    String[] parts = date.split(" ");
    int month = Integer.parseInt(parts[0]);
    int day = Integer.parseInt(parts[1]);
    int year = Integer.parseInt(parts[2]);

    java.util.Calendar cal = java.util.Calendar.getInstance();
    cal.setLenient(false);
    cal.set(year, month - 1, day);
    int weekDayIndex = cal.get(java.util.Calendar.DAY_OF_WEEK); // 1=Sunday, 2=Monday, ..., 7=Saturday

    String[] monthNames = {
        "January", "February", "March", "April", "May", "June",
        "July", "August", "September", "October", "November", "December"
    };
    String[] weekDayNames = {
        "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"
    };

    String monthName = monthNames[month - 1];
    String weekDayName = weekDayNames[weekDayIndex - 1];

    return monthName + " " + day + ", " + year + " is a " + weekDayName;
}

public static String convertDatesToWeekdays(String date) {
    java.time.format.DateTimeFormatter inputFormatter = java.time.format.DateTimeFormatter.ofPattern("MM dd yyyy");
    java.time.LocalDate localDate = java.time.LocalDate.parse(date, inputFormatter);
    java.time.format.DateTimeFormatter outputFormatter = java.time.format.DateTimeFormatter.ofPattern("MMMM d, yyyy");
