    String dayName = localDate.getDayOfWeek().getDisplayName(TextStyle.FULL, Locale.ENGLISH);
    return String.format("%s %d, %d is a %s", monthName, day, year, dayName);
}

public int[] twoSum(int[] nums, int target) {
    java.util.Map<Integer, Integer> numMap = new java.util.HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        if (numMap.containsKey(complement)) {
            return new int[]{numMap.get(complement), i};
        }
        numMap.put(nums[i], i);
    }
    return new int[]{-1, -1};
}

