public double trimMean(int[] arr) {
    int n = arr.length;
    int remove = n / 20;
    java.util.Arrays.sort(arr);
    long sum = 0;
    for (int i = remove; i < n - remove; i++) {
        sum += arr[i];
    }
    return (double) sum / (n - 2 * remove);
}

