public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 != 0) return false; // array length must be even

    int[] freq = new int[k];
    for (int val : arr) {
        int r = ((val % k) + k) % k; // handle negative numbers
        freq[r]++;
    }

    if (freq[0] % 2 != 0) return false; // 0 remainders must pair among themselves

    if (k % 2 == 0) {
        // when k is even, remainder k/2 must pair among themselves
        if (freq[k / 2] % 2 != 0) return false;
        for (int r = 1; r < k / 2; r++) {
            if (freq[r] != freq[k - r]) return false;
        }
    } else {
        for (int r = 1; r <= k / 2; r++) {
            if (freq[r] != freq[k - r]) return false;
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    int[] count = new int[k];
    for (int num : arr) {
        int rem = Math.floorMod(num, k);
        count[rem]++;
    }
    // Remainder 0 must be even
    if (count[0] % 2 != 0) return false;
    // If k even, remainder k/2 must be even
    if (k % 2 == 0 && count[k / 2] % 2 != 0) return false;
    // Check pairs of remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) continue; // already handled when k even
        if (count[r] != count[k - r]) return false;
    }
    return true;
}

