    if (count[0] % 2 != 0) return false;
    // If k is even, remainder k/2 must also pair among themselves
    if (k % 2 == 0) {
        if (count[k / 2] % 2 != 0) return false;
    }
    // For all other remainders, counts must match complementary remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) continue; // already handled when k even
        if (count[r] != count[k - r]) {
            return false;
        }
    }
    return true;
}

