    int[] count = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k;
        count[rem]++;
    }
    // Remainder 0 must have even count
    if (count[0] % 2 != 0) return false;
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) { // this occurs when k is even and r == k/2
            if (count[r] % 2 != 0) return false;
        } else {
            if (count[r] != count[complement]) return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    for (int[] e : edges) {
        graph[e[0]].add(e[1]);
        graph[e[1]].add(e[0]);
    }
    return dfs(0, -1, graph, hasApple);
}

private int dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple) {
    int time = 0;
    for (int nei : graph[node]) {
        if (nei == parent) continue;
        int childTime = dfs(nei, node, graph, hasApple);
        if (childTime > 0 || hasApple[nei]) {
            time += childTime + 2;
        }
    }
    return time;
}

int dfs(int node, int parent) {
  int total = 0;
  boolean hasAppleInSubtree = hasApple[node];
  for (int child : adj[node]) {
    if (child == parent) continue;
    int childTime = dfs(child, node);
    if (childTime > 0) {
      total += childTime + 2;
    }
    hasAppleInSubtree |= (childTime > 0);
  }
  return hasAppleInSubtree ? total : 0;
}

