private boolean dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple, int[] total) {
    boolean has = hasApple[node];
    for (int nxt : graph[node]) {
        if (nxt == parent) continue;
        boolean childHas = dfs(nxt, node, graph, hasApple, total);
        if (childHas) {
            total[0] += 2;
            has = true;
        }
    }
    return has;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] e : edges) {
        int u = e[0], v = e[1];
        graph[u].add(v);
        graph[v].add(u);
    }
    boolean[] visited = new boolean[n];
    return dfs(0, graph, hasApple, visited);
}

private int dfs(int node, List<Integer>[] graph, boolean[] hasApple, boolean[] visited) {
    visited[node] = true;
    int total = 0;
    for (int nei : graph[node]) {
        if (!visited[nei]) {
            int childTime = dfs(nei, graph, hasApple, visited);
            if (childTime > 0 || hasApple[nei]) {
                total += childTime + 2;
            }
        }
    }
    return total;
}

