public String sortString(String s) {
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        freq[c - 'a']++;
    }
    StringBuilder result = new StringBuilder();
    int remaining = s.length();
    while (remaining > 0) {
        // Ascending pass: pick smallest then smallest greater than last
        int start = -1;
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                start = i;
                break;
            }
        }
        if (start == -1) break;
        result.append((char) (start + 'a'));
        freq[start]--;
        remaining--;
        int last = start;
        while (true) {
            int next = -1;
            for (int i = last + 1; i < 26; i++) {
                if (freq[i] > 0) {
                    next = i;
                    break;
                }
            }
            if (next == -1) break;
            result.append((char) (next + 'a'));
            freq[next]--;
            remaining--;
            last = next;
        }

        // Descending pass: pick largest then largest smaller than last
        int descStart = -1;
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                descStart = i;
                break;
            }
        }
        if (descStart == -1) break;
        result.append((char) (descStart + 'a'));
        freq[descStart]--;
        remaining--;
        last = descStart;
        while (true) {
            int next = -1;
            for (int i = last - 1; i >= 0; i--) {
                if (freq[i] > 0) {
                    next = i;
                    break;
                }
            }
            if (next == -1) break;
            result.append((char) (next + 'a'));
            freq[next]--;
            remaining--;
            last = next;
        }
    }
    return result.toString();
}

public String sortString(String s) {
    int n = s.length();
    int[] freq = new int[256];
    for (int i = 0; i < n; i++) {
        freq[s.charAt(i)]++;
    }

    StringBuilder result = new StringBuilder();

    while (result.length() < n) {
        // Ascending phase
        int last = -1;
        for (int c = 0; c < 256; c++) {
            if (freq[c] > 0) {
                result.append((char) c);
                freq[c]--;
                last = c;
                break;
            }
        }
        if (last == -1) {
            break; // no characters left
        }
        for (int c = last + 1; c < 256; c++) {
            if (freq[c] > 0) {
                result.append((char) c);
                freq[c]--;
                last = c;
            }
        }

        // Descending phase
        int lastDesc = -1;
        for (int c = 255; c >= 0; c--) {
            if (freq[c] > 0) {
                result.append((char) c);
                freq[c]--;
                lastDesc = c;
                break;
            }
        }
        if (lastDesc == -1) {
            break; // no characters left
        }
        for (int c = lastDesc - 1; c >= 0; c--) {
            if (freq[c] > 0) {
                result.append((char) c);
                freq[c]--;
                lastDesc = c;
            }
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    long totalSum = 0;
    for (int v : nums) totalSum += v;
    java.util.List<java.util.HashSet<Integer>> subsets = new java.util.ArrayList<>(n + 1);
    for (int i = 0; i <= n; i++) subsets.add(new java.util.HashSet<>());
    subsets.get(0).add(0);
    for (int num : nums) {
        for (int sz = n - 1; sz >= 1; sz--) {
            java.util.Set<Integer> prevSet = subsets.get(sz - 1);
            java.util.HashSet<Integer> curSet = subsets.get(sz);
            if (prevSet.isEmpty()) continue;
            if (totalSum * sz % n == 0) {
                int target = (int) (totalSum * sz / n);
                for (int pre : prevSet) {
                    int newSum = pre + num;
                    if (newSum == target) return true;
                    curSet.add(newSum);
                }
            } else {
                for (int pre : prevSet) {
                    curSet.add(pre + num);
                }
            }
        }
    }
    return false;
}

