        int target = (totalSum * k) / n;
        if (hasSubset(nums, target, k, 0)) {
            return true;
        }
    }
    return false;
}

private boolean hasSubset(int[] nums, int target, int k, int start) {
    if (k == 0) {
        return target == 0;
    }
    if (k == 1) {
        for (int i = start; i < nums.length; i++) {
            if (nums[i] == target) {
                return true;
            }
        }
        return false;
    }
    int n = nums.length;
    for (int i = start; i <= n - k; i++) {
        if (hasSubset(nums, target - nums[i], k - 1, i + 1)) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) {
        return false;
    }
    int totalSum = 0;
    for (int val : nums) {
        totalSum += val;
    }
    // Prepare lists of sets to store possible sums for each subset size
    java.util.List<java.util.Set<Integer>> subsetSums = new java.util.ArrayList<>(n + 1);
    for (int i = 0; i <= n; i++) {
        subsetSums.add(new java.util.HashSet<>());
    }
    subsetSums.get(0).add(0); // Empty subset has sum 0
    int currentMaxSize = 0;
    for (int num : nums) {
        currentMaxSize++;
        // Update in reverse order to avoid using the same element twice
        for (int sz = currentMaxSize; sz >= 1; sz--) {
            java.util.Set<Integer> prevSet = subsetSums.get(sz - 1);
            java.util.Set<Integer> currentSet = subsetSums.get(sz);
            for (int prevSum : prevSet) {
                currentSet.add(prevSum + num);
            }
        }
    }
    // Check for any feasible subset size k
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) {
            continue; // average cannot be integer
        }
        int targetSum = (totalSum * k) / n;
        if (subsetSums.get(k).contains(targetSum)) {
            return true;
        }
    }
    return false;
}

