public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int total = 0;
    for (int num : nums) total += num;
    int maxMask = 1 << n;
    // Precompute subset sizes and sums for each mask? We'll compute on the fly.
    // However we need to check each k and target; we can iterate all subsets once and store in map by size and sum.
    Map<Integer, Set<Integer>> sumsBySize = new HashMap<>();
    for (int mask = 1; mask < maxMask; mask++) {
        int sum = 0;
        int cnt = 0;
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[i];
                cnt++;
            }
        }
        sumsBySize.computeIfAbsent(cnt, k -> new HashSet<>()).add(sum);
    }
    for (int k = 1; k < n; k++) {
        if ((total * k) % n != 0) continue;
        int target = (total * k) / n;
        if (sumsBySize.containsKey(k) && sumsBySize.get(k).contains(target)) {
            return true;
        }
    }
    return false;
}

private boolean hasSubset(int[] nums, int idx, int k, int target, int currentSum){
   if(k==0) return currentSum==target;
   if(idx==nums.length) return false;
   // choose current
   if(hasSubset(nums, idx+1, k-1, target, currentSum+nums[idx])) return true;
   // skip
   return hasSubset(nums, idx+1, k, target, currentSum);
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int total = 0;
    for (int v : nums) total += v;

    boolean[][] dp = new boolean[n + 1][total + 1];
    dp[0][0] = true;

    for (int num : nums) {
        for (int sz = n - 1; sz >= 0; sz--) {
            for (int s = 0; s + num <= total; s++) {
                if (dp[sz][s]) {
                    dp[sz + 1][s + num] = true;
                }
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        long prod = 1L * total * k;
        if (prod % n != 0) continue;
        int target = (int) (prod / n);
        if (dp[k][target]) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
