    if (n == 0) return 0;
    int prev2 = 0; // cost to reach step -1 (virtual before first step)
    int prev1 = 0; // cost to reach step 0
    for (int i = 1; i <= n; i++) {
        int current = Math.min(prev1 + cost[i - 1], prev2 + (i - 2 >= 0 ? cost[i - 2] : 0));
        prev2 = prev1;
        prev1 = current;
    }
    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    // dp[i] represents the minimum cost to reach step i
    // dp[0] and dp[1] are 0 because we can start at step 0 or 1 without paying
    int dpPrev2 = 0; // dp[i-2]
    int dpPrev1 = 0; // dp[i-1]
    int curr = 0;
    for (int i = 2; i <= n; i++) {
        // When reaching step i, we need to pay the cost of the step we land on
        // That step is either i-1 or i-2
        curr = Math.min(dpPrev1 + cost[i - 1], dpPrev2 + cost[i - 2]);
        dpPrev2 = dpPrev1;
        dpPrev1 = curr;
    }
    // dpPrev1 now holds dp[n], the minimum cost to reach the top
    return dpPrev1;
}

