public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true;
    int n = s.length();
    if (n < k) return false;
    int total = 1 << k; // number of possible k-bit codes
    boolean[] seen = new boolean[total];
    int count = 0;
    int mask = total - 1;
    int code = 0;
    for (int i = 0; i < n; i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[code]) {
                seen[code] = true;
                count++;
                if (count == total) {
                    return true;
                }
            }
        }
    }
    return false;
}

public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (k > n) {
        return false;
    }
    int required = 1 << k;
    // If the maximum number of substrings is less than required codes, impossible
    if (n - k + 1 < required) {
        return false;
    }
    boolean[] seen = new boolean[required];
    int mask = required - 1;
    int val = 0;
    int seenCount = 0;
    for (int i = 0; i < n; i++) {
        val = ((val << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[val]) {
                seen[val] = true;
                seenCount++;
                if (seenCount == required) {
                    return true;
                }
            }
        }
    }
    return seenCount == required;
}

