}

public boolean hasAllCodes(String s, int k) {
    if (s == null) return false;
    int n = s.length();
    if (k <= 0 || n < k) return false; // cannot contain all codes

    int total = 1 << k; // number of possible binary strings of length k
    boolean[] seen = new boolean[total];
    int mask = total - 1; // e.g., if k=3, mask=0b111
    int val = 0;

    for (int i = 0; i < n; i++) {
        // Build the current k-length window value
        val = ((val << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[val]) {
                seen[val] = true;
                // early exit if all codes found
                // we could keep a counter, but checking all after loop is fine
            }
        }
    }

    // Verify every code has been seen
    for (boolean b : seen) {
        if (!b) return false;
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true; // trivial case
    int n = s.length();
    int total = 1 << k;
    if (n < total) return false; // not enough substrings to cover all codes

    boolean[] seen = new boolean[total];
    int mask = total - 1;

    // Build the first code of length k
    int code = 0;
    for (int i = 0; i < k; i++) {
        code = (code << 1) | (s.charAt(i) - '0');
    }
    seen[code] = true;
    int count = 1;

    // Slide window through the string
    for (int i = k; i < n; i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[code]) {
            seen[code] = true;
            if (++count == total) {
                return true; // all codes found early
            }
        }
    }
    return count == total;
}

