public int minInsertions(String s) {
    int res = 0;
    int balance = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance == 0) {
                res++; // insert a '(' before this ')'
            } else {
                balance--; // match this ')'
            }
        }
    }
    res += balance; // insert ')' for unmatched '('
    return res;
}

public int minInsertions(String s) {
    int insertions = 0;
    int neededOpen = 0; // number of unmatched '('

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            neededOpen++;
        } else if (c == ')') {
            if (neededOpen == 0) {
                // Need an opening bracket before this ')'
                insertions++;
            } else {
                neededOpen--;
            }
        }
    }

    // Add closing brackets for all remaining unmatched '('
    return insertions + neededOpen;
}

public int minInsertions(String s) {
    int balance = 0; // number of unmatched '('
    int insertions = 0; // number of insert operations needed

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance == 0) {
                // Need to insert a '(' before this ')'
                insertions++;
                balance++;
            }
            balance--; // match this ')' with an '('
        }
    }

    // Any remaining unmatched '(' need a ')' inserted
    insertions += balance;
    return insertions;
}

