    if (s == null || s.isEmpty()) {
        return 0;
    }
    int opensNeeded = 0;   // number of '(' we need to add
    int unmatchedLeft = 0; // number of '(' that are unmatched so far
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            unmatchedLeft++;
        } else if (c == ')') {
            if (unmatchedLeft > 0) {
                unmatchedLeft--; // match with a previous '('
            } else {
                opensNeeded++;   // need an '(' before this ')'
            }
        }
    }
    return opensNeeded + unmatchedLeft;
}

public int minInsertions(String s) {
    int add = 0;
    int balance = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance > 0) {
                balance--;
            } else {
                // Need an extra '(' to match this ')'
                add++;
                // After inserting '(' before this ')', the balance remains zero
            }
        }
    }
    // Any remaining unmatched '(' require a ')'
    return add + balance;
}

