public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    int[] fib = new int[50]; // 50 is enough for k up to 1e9
    fib[0] = 1;
    fib[1] = 1;
    int size = 2;
    while (true) {
        int next = fib[size - 1] + fib[size - 2];
        if (next > k) break;
        fib[size++] = next;
    }

    // Greedy selection of largest possible Fibonacci numbers
    int count = 0;
    int remaining = k;
    for (int i = size - 1; i >= 0 && remaining > 0; i--) {
        if (remaining >= fib[i]) {
            remaining -= fib[i];
            count++;
        }
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    // Generate all Fibonacci numbers less than or equal to k
    java.util.ArrayList<Integer> fibs = new java.util.ArrayList<>();
    int a = 1, b = 1;
    fibs.add(a);
    fibs.add(b);
    while (true) {
        int c = a + b;
        if (c > k) break;
        fibs.add(c);
        a = b;
        b = c;
    }
    // Greedy selection of largest Fibonacci numbers
    int count = 0;
    int remaining = k;
    int idx = fibs.size() - 1;
    while (remaining > 0) {
        while (fibs.get(idx) > remaining) {
            idx--;
        }
        remaining -= fibs.get(idx);
        count++;
    }
    return count;
}

