public int kthFactor(int n, int k) {
    java.util.List<Integer> factors = new java.util.ArrayList<>();
    for (int i = 1; (long)i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    if (k <= factors.size()) {
        return factors.get(k - 1);
    } else {
        return -1;
    }
}

public int kthFactor(int n, int k) {
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (i != other) {
                large.add(other);
            }
        }
    }
    int total = small.size() + large.size();
    if (k > total) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        int offset = k - small.size();
        return large.get(large.size() - offset);
    }
}

public int kthFactor(int n, int k) {
    List<Integer> small = new ArrayList<>();
    List<Integer> large = new ArrayList<>();
    int sqrtN = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrtN; i++) {
        if (n % i == 0) {
            small.add(i);
            int counterpart = n / i;
            if (counterpart != i) {
                large.add(counterpart);
            }
        }
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    }
    k -= small.size();
    if (k <= large.size()) {
        // large list is in descending order; need ascending
        // so the k-th smallest among large is at position large.size() - k
        return large.get(large.size() - k);
    }
    return -1;
}

