private int dfs(int index, String s, Set<String> seen) {
    if (index == s.length()) {
        return 0;
    }
    int max = 0;
    for (int end = index + 1; end <= s.length(); end++) {
        String part = s.substring(index, end);
        if (!seen.contains(part)) {
            seen.add(part);
            int count = 1 + dfs(end, s, seen);
            if (count > max) {
                max = count;
            }
            seen.remove(part);
        }
    }
    return max;
}

