}

private int dfs(int index, java.util.Set<String> seen, String s) {
    if (index == s.length()) {
        return 0;
    }
    int best = 0;
    for (int i = index; i < s.length(); i++) {
        String sub = s.substring(index, i + 1);
        if (!seen.contains(sub)) {
            seen.add(sub);
            int current = 1 + dfs(i + 1, seen, s);
            if (current > best) {
                best = current;
            }
            seen.remove(sub);
        }
    }
    return best;
}

