private int dfs(String s, int idx, java.util.Set<String> seen) {
    if (idx == s.length()) {
        return 0;
    }
    int max = Integer.MIN_VALUE;
    for (int end = idx + 1; end <= s.length(); end++) {
        String sub = s.substring(idx, end);
        if (!seen.contains(sub)) {
            seen.add(sub);
            int res = dfs(s, end, seen);
            seen.remove(sub);
            if (res != Integer.MIN_VALUE) {
                max = Math.max(max, 1 + res);
            }
        }
    }
    return max;
}

