private int dfs(int index, String s, java.util.Set<String> used) {
    if (index == s.length()) {
        return used.size();
    }
    int maxParts = 0;
    for (int end = index + 1; end <= s.length(); end++) {
        String part = s.substring(index, end);
        if (!used.contains(part)) {
            used.add(part);
            maxParts = Math.max(maxParts, dfs(end, s, used));
            used.remove(part);
        }
    }
    return maxParts;
}

public int maxUniqueSplit(String s) {
    int[] maxCount = new int[]{0};
