}

private void dfs(String s, int pos, java.util.Set<String> used, int[] maxCount) {
    if (pos == s.length()) {
        maxCount[0] = Math.max(maxCount[0], used.size());
        return;
    }
    for (int end = pos + 1; end <= s.length(); end++) {
        String part = s.substring(pos, end);
        if (!used.contains(part)) {
            used.add(part);
            dfs(s, end, used, maxCount);
            used.remove(part);
        }
    }
}

