public String getSmallestString(int n, int k) {
    if (n <= 0) {
        return "";
    }
    int needed = k - n; // amount of additional value to reach k
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    for (int i = n - 1; i >= 0 && needed > 0; i--) {
        int add = Math.min(25, needed); // each position can increase up to 25 (from 'a' to 'z')
        result[i] = (char) ('a' + add);
        needed -= add;
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    if (n <= 0) return "";
    // Minimum sum achievable is n (all 'a's). If k is less, there's no solution, but assume valid input.
    char[] result = new char[n];
    java.util.Arrays.fill(result, 'a');
    int remaining = k - n; // how much extra sum we need to distribute
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // each position can be increased by at most 25 ('a'->'z')
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    // Start with all 'a's, which gives the minimal lexicographic order.
    char[] chars = new char[n];
    Arrays.fill(chars, 'a');
    int remaining = k - n; // total value we still need to add
    // Distribute the remaining value from the end to preserve lexicographic minimality.
    for (int i = n - 1; remaining > 0 && i >= 0; i--) {
        int add = Math.min(25, remaining); // we can add at most 25 ('z' - 'a')
        chars[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(chars);
}

public String getSmallestString(int n, int k) {
    // Initialize the result array with 'a' which has value 1
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }

    // Subtract the minimum sum contributed by all 'a's
    int remaining = k - n;

    // Distribute remaining value from the end to make the string lexicographically smallest
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // 'a' + 25 -> 'z'
        result[i] = (char)('a' + add);
        remaining -= add;
    }

    return new String(result);
}

public String getSmallestString(int n, int k) {
    if (k < n || k > 26 * n) {
