    }
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int remaining = k - n; // the extra value needed over all 'a'
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining);
        result[i] = (char) (result[i] + add);
