public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    String sign = n < 0 ? "-" : "";
    int absVal = Math.abs(n);
    StringBuilder sb = new StringBuilder(String.valueOf(absVal));
    int i = sb.length() - 3;
    while (i > 0) {
        sb.insert(i, '.');
        i -= 3;
    }
    return sign + sb.toString();
}

public static String addThousandSeparator(int n) {
    boolean negative = n < 0;
    long absVal = Math.abs((long)n);
    String s = Long.toString(absVal);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    for (int i = s.length() - 1; i >= 0; i--) {
        sb.append(s.charAt(i));
        count++;
        if (count == 3 && i != 0) {
            sb.append('.');
            count = 0;
        }
    }
    if (negative) sb.append('-');
    return sb.reverse().toString();
}

