public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    int[] arr = A.clone();
    java.util.Arrays.sort(arr);
    // Precompute perfect squares up to the maximum possible sum
    int maxVal = arr[n - 1];
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int k = 0; k * k <= maxSum; k++) {
        isSquare[k * k] = true;
    }

    boolean[] used = new boolean[n];
    return dfs(0, -1, arr, used, isSquare);
}

private static int dfs(int pos, int lastIdx, int[] arr, boolean[] used, boolean[] isSquare) {
    int n = arr.length;
    if (pos == n) return 1; // a valid permutation
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (used[i]) continue;
        // Skip duplicates: if the current value equals previous and previous not used in this level
        if (i > 0 && arr[i] == arr[i - 1] && !used[i - 1]) continue;
        if (pos > 0) {
            int sum = arr[lastIdx] + arr[i];
            if (!isSquare[sum]) continue;
        }
        used[i] = true;
        count += dfs(pos + 1, i, arr, used, isSquare);
        used[i] = false;
    }
    return count;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Sort to handle duplicates
    java.util.Arrays.sort(A);
    // Find maximum possible sum to precompute perfect squares
    int maxVal = 0;
    for (int v : A) {
        if (v > maxVal) maxVal = v;
    }
    int maxSum = maxVal * 2;
    boolean[] isSq = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSq[i * i] = true;
    }
    int fullMask = (1 << n) - 1;
    long[][] dp = new long[1 << n][n];
    // Initialize dp for single-element masks
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }
    // Populate DP
    for (int mask = 1; mask <= fullMask; mask++) {
        for (int last = 0; last < n; last++) {
            long curCount = dp[mask][last];
            if (curCount == 0) continue;
            for (int j = 0; j < n; j++) {
                if ((mask & (1 << j)) != 0) continue;
                // Skip duplicate values to avoid counting the same permutation multiple times
                if (j > 0 && A[j] == A[j - 1] && (mask & (1 << (j - 1))) == 0) continue;
                int sum = A[last] + A[j];
                if (sum <= maxSum && isSq[sum]) {
                    dp[mask | (1 << j)][j] += curCount;
                }
            }
        }
    }
    long result = 0;
    for (int i = 0; i < n; i++) {
        result += dp[fullMask][i];
    }
    return (int) result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    if (n == 1) return 1;

    // Determine maximum possible sum of two elements
    int maxVal = 0;
    for (int v : A) if (v > maxVal) maxVal = v;
    int maxSum = maxVal * 2 + 1;

    // Precompute perfect squares up to maxSum
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int sq = 1; sq * sq <= maxSum; sq++) {
        isSquare[sq * sq] = true;
    }

    // Precompute adjacency matrix: can i -> j if A[i] + A[j] is a perfect square
    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j && isSquare[A[i] + A[j]]) {
                can[i][j] = true;
            }
        }
    }

    // DP with memoization: key = (mask * n + lastIndex)
    java.util.HashMap<Integer, Integer> memo = new java.util.HashMap<>();

    java.util.function.BiFunction<Integer, Integer, Integer> dfs = new java.util.function.BiFunction<Integer, Integer, Integer>() {
        @Override
        public Integer apply(Integer mask, Integer last) {
            if (mask == (1 << n) - 1) {
                return 1;
            }
            int key = mask * n + last;
            if (memo.containsKey(key)) {
                return memo.get(key);
            }
            int result = 0;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) == 0 && can[last][next]) {
                    result += apply(mask | (1 << next), next);
                }
