        int iEnd = Math.min(m - 1, d);
        if (d % 2 == 0) {
            // even diagonal: traverse from iEnd down to iStart
            for (int i = iEnd; i >= iStart; i--) {
                int j = d - i;
                res[idx++] = mat[i][j];
            }
        } else {
            // odd diagonal: traverse from iStart up to iEnd
            for (int i = iStart; i <= iEnd; i++) {
                int j = d - i;
                res[idx++] = mat[i][j];
            }
        }
    }
    return res;
}

