        }
    }

private String buildMirrorString(char[] half, Map<Character, Character> map) {
        StringBuilder sb = new StringBuilder();
        for (int i = half.length - 1; i >= 0; i--) {
            sb.append(map.get(half[i]));
        }
        return sb.toString();
    }

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[] current = new char[n];
    build(0, n - 1, current, result);
    return result;
}

private static void build(int left, int right, char[] current, List<String> result) {
    if (left > right) {
        result.add(new String(current));
        return;
    }
    if (left == right) {
        char[] mids = {'0', '1', '8'};
        for (char mid : mids) {
            current[left] = mid;
            build(left + 1, right - 1, current, result);
        }
    } else {
        char[][] pairs = {{'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}};
        for (char[] pair : pairs) {
            if (left == 0 && pair[0] == '0') {
                continue; // avoid leading zero
            }
            current[left] = pair[0];
            current[right] = pair[1];
            build(left + 1, right - 1, current, result);
        }
    }
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int[] p1 = points[0], p2 = points[1], p3 = points[2];
    if ((p1[0] == p2[0] && p1[1] == p2[1]) ||
        (p1[0] == p3[0] && p1[1] == p3[1]) ||
        (p2[0] == p3[0] && p2[1] == p3[1])) {
        return false;
    }
    long area = (long)(p2[0] - p1[0]) * (p3[1] - p1[1]) -
                (long)(p2[1] - p1[1]) * (p3[0] - p1[0]);
    return area != 0;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    // Check for duplicate points
    for (int i = 0; i < 3; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                return false;
            }
        }
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    // Compute 2 * area of triangle using cross product
    int area2 = (x1 - x3) * (y2 - y3) - (x2 - x3) * (y1 - y3);
    return area2 != 0;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Ensure all points are distinct
    if ((x1 == x2 && y1 == y2) || (x1 == x3 && y1 == y3) || (x2 == x3 && y2 == y3)) {
        return false;
    }

    // Compute twice the signed area of the triangle
    long area2 = (long) x1 * (y2 - y3) + (long) x2 * (y3 - y1) + (long) x3 * (y1 - y2);

    // If the area is zero, points are colinear; hence not a boomerang
    return area2 != 0;
}

