    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int candidate = dp[i - j * j] + 1;
            if (candidate < min) {
                min = candidate;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = n + 1; // a value larger than any possible result
    }
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // maximum possible (1^2 + 1^2 + ... + 1^2)
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            dp[i] = Math.min(dp[i], dp[i - square] + 1);
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    if (isPerfectSquare(n)) {
        return 1;
    }
    for (int i = 1; i * i <= n; i++) {
        int remaining = n - i * i;
        if (isPerfectSquare(remaining)) {
            return 2;
        }
    }
    int m = n;
    while (m % 4 == 0) {
        m /= 4;
    }
    if (m % 8 == 7) {
        return 4;
    }
    return 3;
}

private static boolean isPerfectSquare(int x) {
    int sqrt = (int) Math.sqrt(x);
    return sqrt * sqrt == x;
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    String[] words = s.split(" ");
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        for (int j = word.length() - 1; j >= 0; j--) {
            sb.append(word.charAt(j));
        }
        if (i < words.length - 1) {
            sb.append(' ');
        }
    }
    return sb.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            // Append reversed word
            for (int j = word.length() - 1; j >= 0; j--) {
                result.append(word.charAt(j));
            }
            word.setLength(0);
            result.append(c);
        } else {
            word.append(c);
        }
    }
    // Append reversed of the last word (if any)
    for (int j = word.length() - 1; j >= 0; j--) {
        result.append(word.charAt(j));
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder current = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(current.reverse());
            result.append(' ');
            current.setLength(0);
        } else {
            current.append(c);
        }
    }
    // append the last word
    result.append(current.reverse());
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    StringBuilder result = new StringBuilder();
    int i = 0;
    int n = s.length();
    while (i < n) {
        // Preserve spaces as is
        if (s.charAt(i) == ' ') {
            result.append(' ');
            i++;
            continue;
        }
        // Find the end of the current word
        int wordStart = i;
        while (i < n && s.charAt(i) != ' ') {
            i++;
        }
        // Reverse the word characters
        for (int j = i - 1; j >= wordStart; j--) {
            result.append(s.charAt(j));
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    int n = s.length();
    StringBuilder result = new StringBuilder(n);
    int startWord = -1;

    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            if (startWord != -1) {
                // End of a word
                result.append(new StringBuilder(s, startWord, i - startWord).reverse());
                startWord = -1;
            }
            // Append the space itself
            result.append(c);
        } else {
            if (startWord == -1) {
                startWord = i;
            }
        }
    }

    // Handle the last word if string does not end with space
    if (startWord != -1) {
        result.append(new StringBuilder(s, startWord, n - startWord).reverse());
    }

    return result.toString();
}
